SELECT 
  p.address,
  p.name,
  u.unit_number,
  u.bedrooms,
  u.bathrooms,
  u.square_feet,
  u.status
FROM properties p
LEFT JOIN units u ON p.id = u.property_id
ORDER BY p.address, u.unit_number;
